def _read_excel_fast(_src, **kwargs):
    """Lê Excel priorizando o engine 'calamine' (5–10x mais rápido que o openpyxl);
    se o pacote não estiver instalado ou falhar, cai automaticamente para o engine
    padrão. Reposiciona o buffer entre tentativas (evita leitura corrompida quando a
    fonte é um BytesIO). O resultado é o mesmo — só muda a velocidade. Sem regressão."""
    import pandas as _pd
    def _rewind():
        try:
            if hasattr(_src, "seek"):
                _src.seek(0)
        except Exception:
            pass
    _rewind()
    try:
        return _pd.read_excel(_src, engine="calamine", **kwargs)
    except Exception:
        _rewind()
        return _pd.read_excel(_src, **kwargs)


def _excelfile_fast(_src):
    """Abre um ExcelFile priorizando o engine 'calamine', com fallback ao padrão e
    reposicionamento do buffer entre tentativas."""
    import pandas as _pd
    def _rewind():
        try:
            if hasattr(_src, "seek"):
                _src.seek(0)
        except Exception:
            pass
    _rewind()
    try:
        return _pd.ExcelFile(_src, engine="calamine")
    except Exception:
        _rewind()
        return _pd.ExcelFile(_src)


def _dist_km(serie):
    """Converte NU_DISTANCIA para KM com AUTO-DETECÇÃO de unidade.
    Os microdados reais do INEP trazem NU_DISTANCIA já em km (mediana de poucos
    km; ex.: MT com média ~3 km, máx ~117 km). Bases sintéticas/antigas podem vir
    em metros (mediana de milhares). Regra: se a mediana dos valores positivos for
    >= 100, assume METROS e divide por 1000; caso contrário, já está em KM.
    Isso mantém o comportamento correto tanto no demo (metros) quanto na base real
    (km), sem regressão."""
    import pandas as _pd
    _s = _pd.to_numeric(serie, errors="coerce")
    _pos = _s[_s.notna() & (_s > 0)]
    try:
        if len(_pos) and float(_pos.median()) >= 100:
            return _s / 1000.0
    except Exception:
        pass
    return _s
