        if not _avail:
            _avail = ['N02', 'N50', 'N52', 'N60', 'N90', 'N91']  # sem info → assume todos
        html_content = html_content.replace('JSON_AVAILABLE_LAYOUTS', json.dumps(_avail, ensure_ascii=True))
