            _catc = _achar_col(_df_acc.columns, ["DESCRICAO", "TIPO", "ACESSIBILIDADE", "NOME", "ITEM"])
            _numc = _achar_col(_df_acc.columns, ["QT", "TOTAL", "COUNT", "NUM", "LOCAL", "VALOR"])
            if _catc and _numc:
                _dplot = _df_acc[[_catc, _numc]].copy()
